{"explanation":"The matrix sends [1m(x,y)[0m to [1m(2x+y,y)[0m: it doubles the horizontal component and shears by the vertical component. The unit square becomes a parallelogram with area 2, exactly the determinant [1mdet(A)=2[0m. Drag the yellow point to see a vector and its image move together.","manimCode":"const s = 0.72;
const leftC = [-3.1, -0.35, 0];
const rightC = [3.0, -0.35, 0];

const title = new MathTex({ latex: 'A=\\begin{pmatrix}2&1\\\\0&1\\end{pmatrix},\\qquad \\det(A)=2' });
await title.waitForRender();
title.moveTo([0, 3.15, 0]);

const leftLabel = new Text({ text: 'Original plane', color: BLUE_B, fontSize: 25 });
leftLabel.moveTo([-3.1, 2.25, 0]);
const rightLabel = new Text({ text: 'Transformed plane', color: GREEN_B, fontSize: 25 });
rightLabel.moveTo([3.0, 2.25, 0]);

function segment(a, b, color, width) {
  const seg = new Polygon({ vertices: [a, b], color: color });
  seg.setFillOpacity(0);
  seg.setStrokeWidth(width || 1);
  return seg;
}

const grid = [];
for (let k = -2; k <= 2; k++) {
  grid.push(segment([leftC[0] - 2*s, leftC[1] + k*s, 0], [leftC[0] + 2*s, leftC[1] + k*s, 0], GRAY, 1));
  grid.push(segment([leftC[0] + k*s, leftC[1] - 2*s, 0], [leftC[0] + k*s, leftC[1] + 2*s, 0], GRAY, 1));
  // Images of horizontal and vertical grid lines under A
  grid.push(segment([rightC[0] + (-4 + k)*s, rightC[1] + k*s, 0], [rightC[0] + (4 + k)*s, rightC[1] + k*s, 0], GRAY, 1));
  grid.push(segment([rightC[0] + (2*k - 2)*s, rightC[1] - 2*s, 0], [rightC[0] + (2*k + 2)*s, rightC[1] + 2*s, 0], GRAY, 1));
}

const xAxisL = segment([leftC[0] - 2.1*s, leftC[1], 0], [leftC[0] + 2.1*s, leftC[1], 0], WHITE, 2);
const yAxisL = segment([leftC[0], leftC[1] - 2.1*s, 0], [leftC[0], leftC[1] + 2.1*s, 0], WHITE, 2);
const xAxisR = segment([rightC[0] - 4.3*s, rightC[1], 0], [rightC[0] + 4.3*s, rightC[1], 0], WHITE, 2);
const yAxisR = segment([rightC[0] - 2.1*s, rightC[1] - 2.1*s, 0], [rightC[0] + 2.1*s, rightC[1] + 2.1*s, 0], WHITE, 2);

const unitSquare = new Polygon({ vertices: [leftC, [leftC[0]+s,leftC[1],0], [leftC[0]+s,leftC[1]+s,0], [leftC[0],leftC[1]+s,0]], color: BLUE });
unitSquare.setFill(BLUE, 0.38).setStrokeWidth(3);
const imageSquare = new Polygon({ vertices: [rightC, [rightC[0]+2*s,rightC[1],0], [rightC[0]+3*s,rightC[1]+s,0], [rightC[0]+s,rightC[1]+s,0]], color: GREEN });
imageSquare.setFill(GREEN, 0.38).setStrokeWidth(3);

const areaLeft = new MathTex({ latex: '\\text{area}=1' });
await areaLeft.waitForRender();
areaLeft.moveTo([-3.1, -2.65, 0]);
const areaRight = new MathTex({ latex: '\\text{area}=2=|\\det(A)|' });
await areaRight.waitForRender();
areaRight.moveTo([3.0, -2.65, 0]);

const inputDot = new Dot({ point: [leftC[0] + 0.55*s, leftC[1] + 0.75*s, 0], color: YELLOW });
const outputDot = new Dot({ point: [rightC[0] + 1.85*s, rightC[1] + 0.75*s, 0], color: YELLOW });
const inputVec = segment(leftC, inputDot.getCenter(), YELLOW, 3);
const outputVec = segment(rightC, outputDot.getCenter(), YELLOW, 3);

function updateImage() {
  const p = inputDot.getCenter();
  const x = (p[0] - leftC[0]) / s;
  const y = (p[1] - leftC[1]) / s;
  outputDot.moveTo([rightC[0] + (2*x + y)*s, rightC[1] + y*s, 0]);
  inputVec.setVertices([leftC, inputDot.getCenter()]);
  outputVec.setVertices([rightC, outputDot.getCenter()]);
}

scene.add(...grid, xAxisL, yAxisL, xAxisR, yAxisR, title, leftLabel, rightLabel, unitSquare, imageSquare, areaLeft, areaRight, inputVec, outputVec, inputDot, outputDot);
makeDraggable(inputDot, scene, { constrainX: [-3.9, -2.3], constrainY: [-1.55, 0.85], onDrag: updateImage });
makeHoverable(unitSquare, scene, { hoverOpacity: 0.6 });
makeHoverable(imageSquare, scene, { hoverOpacity: 0.6 });

await scene.wait(999999);"}

